from pathlib import Path
from PIL import Image,ImageDraw
G={
'A':['01110','10001','10001','11111','10001','10001','10001'],'C':['01111','10000','10000','10000','10000','10000','01111'],'E':['11111','10000','10000','11110','10000','10000','11111'],'F':['11111','10000','10000','11110','10000','10000','10000'],'H':['10001','10001','10001','11111','10001','10001','10001'],'I':['111','010','010','010','010','010','111'],'K':['10001','10010','10100','11000','10100','10010','10001'],'L':['10000','10000','10000','10000','10000','10000','11111'],'N':['10001','11001','11001','10101','10011','10011','10001'],'O':['01110','10001','10001','10001','10001','10001','01110'],'R':['11110','10001','10001','11110','10100','10010','10001'],'S':['01111','10000','10000','01110','00001','00001','11110'],'T':['11111','00100','00100','00100','00100','00100','00100'],'U':['10001','10001','10001','10001','10001','10001','01110'],'V':['10001','10001','10001','10001','10001','01010','00100'],'W':['10001','10001','10001','10101','10101','11011','10001']}
im=Image.new('RGB',(820,500),(190,193,177));d=ImageDraw.Draw(im)
def txt(text,x,y,size,col):
 for ch in text:
  if ch==' ':x+=size*4;continue
  glyph=G[ch]
  for yy,row in enumerate(glyph):
   for xx,v in enumerate(row):
    if v=='1':d.rectangle((x+xx*size,y+yy*size,x+(xx+1)*size-1,y+(yy+1)*size-1),fill=col)
  x+=(len(glyph[0])+1)*size
